-- Dev seed: the dev user and the sample lists the lists screens are built against.
--
--   dev@zenbree.local / zenbree-dev-1234, an admin, 6 lists, 457 rows, the chats that own them (a brief and an answer each).
--
-- Dev stack: dev/seed.sh runs it in the running postgres container.
-- Verify stack: bin/stack up runs it; `bin/stack seed` reruns it.
--
-- Skip if present: the user is created only when absent (an existing one only gets the admin role
-- back), and the lists only when that user has none of the seeded ones, so a rerun changes nothing. Seeded rows carry ids derived from the user
-- id, seed_id(user_id || ':' || key), which is how "has the seeded lists" is told apart from
-- the user's own. Ages are relative to now(), so "Oggi" and "Ieri" stay true. Any other user sees
-- the empty state.
--
-- Dev tooling: it lives outside api/db/ (which runs on every fresh volume, prod included), no
-- image copies it and no prod command runs it.
\set ON_ERROR_STOP on
BEGIN;

-- What Better Auth's sign-up writes: user, credential account (scrypt hash from
-- better-auth/crypto's hashPassword) and, from databaseHooks in web/lib/auth.ts, user_credits.
INSERT INTO "user" (name, email, "emailVerified", role, banned)
VALUES ('Dev User', 'dev@zenbree.local', true, 'admin', false)
ON CONFLICT (email) DO UPDATE SET role = 'admin' WHERE "user".role IS DISTINCT FROM 'admin';

-- md5 with the version (4) and variant (10xx) bits set: deterministic, and a valid RFC 4122 v4
-- UUID, which the web's z.uuid() requires (#236).
CREATE FUNCTION pg_temp.seed_id(k text) RETURNS uuid LANGUAGE sql IMMUTABLE AS $$
  SELECT (substr(h, 1, 12) || '4' || substr(h, 14, 3)
          || substr('89ab', (('x' || substr(h, 17, 1))::bit(4)::int & 3) + 1, 1) || substr(h, 18))::uuid
  FROM md5(k) h
$$;

CREATE TEMP TABLE seed_user ON COMMIT DROP AS SELECT id FROM "user" WHERE email = 'dev@zenbree.local';

INSERT INTO account ("accountId", "providerId", "userId", password, "updatedAt")
SELECT id::text, 'credential', id, 'e3c0d7f50ad106a52f4ec6500939b194:6d6cdbdbb4e69ed8de60e6fb307628a35d5b7435465b667aba7780bd86fa43986a62de18da8d7f51c17430c7d291dcb9946a6a93400ddbe4b21c2a16c97eca7c', now() FROM seed_user u
WHERE NOT EXISTS (SELECT 1 FROM account a WHERE a."userId" = u.id AND a."providerId" = 'credential');

INSERT INTO user_credits (organization_id, user_id) SELECT default_organization(id), id FROM seed_user ON CONFLICT DO NOTHING;

-- The default project in the default organization: the chats and lists below take their organization and their project
-- from the same place, so a user who belongs to several organizations gets rows the composite keys accept.
INSERT INTO projects (organization_id, user_id, name, name_is_placeholder)
SELECT default_organization(id), id, 'Il mio cliente', true FROM seed_user u
WHERE NOT EXISTS (SELECT 1 FROM projects p WHERE p.user_id = u.id AND p.organization_id = default_organization(u.id));

