SELECT EXISTS (
  SELECT 1 FROM lists WHERE id IN (
    SELECT pg_temp.seed_id(u.id || ':' || (l->>'id'))
    FROM seed_user u, seed_data, jsonb_array_elements(d->'lists') l
    -- ponytail: a volume seeded before #236 has the plain md5 ids; skip it rather than seed twice.
    -- `bin/stack down` (or dropping those lists) gets the new ids.
    UNION ALL
    SELECT md5(u.id || ':' || (l->>'id'))::uuid
    FROM seed_user u, seed_data, jsonb_array_elements(d->'lists') l)
) AS seeded \gset
\if :seeded
\else

INSERT INTO chat_sessions (id, organization_id, user_id, project_id, title, created_at, updated_at)
SELECT pg_temp.seed_id(u.id || ':' || s.key), default_organization(u.id), u.id,
       (SELECT p.id FROM projects p WHERE p.user_id = u.id AND p.organization_id = default_organization(u.id)
        ORDER BY p.created_at LIMIT 1),
       s.title, now() - s.age_s * interval '1 second', now() - s.age_s * interval '1 second'
FROM seed_user u,
  (SELECT l->>'session' AS key, min(l->>'title') AS title, min((l->>'age_s')::int) AS age_s
   FROM seed_data, jsonb_array_elements(d->'lists') l GROUP BY 1) s
ON CONFLICT (id) DO NOTHING;

-- One brief and one answer per chat, so a seeded chat opens like a finished one: the brief at the chat's creation
-- time, the answer 30 seconds later.
INSERT INTO chat_messages (session_id, user_id, role, content, tool_calls, status, created_at)
SELECT pg_temp.seed_id(u.id || ':' || m.key), u.id, m.role, m.content, m.tool_calls,
       CASE m.role WHEN 'assistant' THEN 'success' END,
       now() - s.age_s * interval '1 second' + m.off_s * interval '1 second'
FROM seed_user u,
  (VALUES
  ('c0ffee00-0000-4000-8000-000000000001', 'user', 'Trovami i CEO e i responsabili commerciali delle agenzie di marketing a Milano con 5-50 dipendenti, meglio se stanno assumendo un SDR. Mi servono le email verificate.', NULL, 0),
  ('c0ffee00-0000-4000-8000-000000000001', 'assistant', 'Ho trovato 31 agenzie di marketing a Milano e 50 persone da contattare. 48 sono consegnate e 47 hanno un’email verificata. In cima ci sono le agenzie con un annuncio aperto per SDR o BDR. Le liste «Agenzie marketing Milano · aziende» e «Agenzie marketing Milano · SDR» sono pronte per una campagna.', '[{"id":"seed-search_companies-company","name":"search_companies","input":{"query":"agenzie di marketing a Milano"},"result":"ok","credits_used":0,"verdict":"success","summary":{"kind":"count","noun":"company","count":31}},{"id":"seed-search_people-person","name":"search_people","input":{"query":"CEO, founder e responsabili commerciali"},"result":"ok","credits_used":0,"verdict":"success","summary":{"kind":"count","noun":"person","count":50}}]'::jsonb, 30),
  ('c0ffee00-0000-4000-8000-000000000002', 'user', 'Cerco i responsabili marketing delle aziende tech italiane tra 50 e 200 dipendenti. Voglio solo chi ha un’email verificata.', NULL, 0),
  ('c0ffee00-0000-4000-8000-000000000002', 'assistant', 'Ho trovato 64 responsabili marketing in aziende tech italiane. 62 sono consegnati con email verificata, per 2 non ho trovato un indirizzo. La lista «Resp. marketing tech 50–200» è ordinata per fit.', '[{"id":"seed-search_people-person","name":"search_people","input":{"query":"responsabili marketing aziende tech Italia 50-200 dipendenti"},"result":"ok","credits_used":0,"verdict":"success","summary":{"kind":"count","noun":"person","count":64}}]'::jsonb, 30),
  ('c0ffee00-0000-4000-8000-000000000003', 'user', 'Fammi un elenco di aziende SaaS italiane che hanno un annuncio aperto per Account Executive.', NULL, 0),
  ('c0ffee00-0000-4000-8000-000000000003', 'assistant', 'Non ho trovato aziende SaaS italiane con un annuncio aperto per Account Executive negli ultimi 30 giorni, quindi la lista «SaaS Italia · AE» è vuota. Posso allargare la ricerca agli ultimi 90 giorni o includere anche i ruoli Sales Development. Dimmi quale preferisci.', '[{"id":"seed-search_companies-company","name":"search_companies","input":{"query":"SaaS Italia annuncio Account Executive"},"result":"ok","credits_used":0,"verdict":"success","summary":{"kind":"count","noun":"company","count":0}}]'::jsonb, 30),
  ('c0ffee00-0000-4000-8000-000000000004', 'user', 'Ho caricato fiere_2026.csv: mancano quasi tutte le email. Trovale per me.', NULL, 0),
  ('c0ffee00-0000-4000-8000-000000000004', 'assistant', 'Ho cercato l’email di 312 contatti di fiere_2026.csv. 193 sono verificate, 48 sono su domini catch-all e per 71 non l’ho trovata. Le 241 righe con un indirizzo sono consegnate nella lista «fiere_2026.csv».', '[{"id":"seed-enrich-email","name":"enrich_email","input":{},"result":"ok","credits_used":0,"verdict":"success","summary":{"kind":"partial","contact":"email","searched":312,"tally":{"found":241,"invalid":0,"not_found":71,"failed":0,"no_source":0,"no_input":0},"unmatched":0,"refunded":0}}]'::jsonb, 30),
  ('c0ffee00-0000-4000-8000-000000000005', 'user', 'Titolari di studi dentistici a Torino, con email e telefono se ci sono.', NULL, 0),
  ('c0ffee00-0000-4000-8000-000000000005', 'assistant', 'Non ho trovato titolari di studi dentistici a Torino con un contatto che posso usare, quindi la lista «Studi dentistici Torino» è vuota. Posso cercare anche nella provincia di Torino o tra i direttori sanitari degli studi. Dimmi come vuoi procedere.', '[{"id":"seed-search_people-person","name":"search_people","input":{"query":"titolari studi dentistici Torino"},"result":"ok","credits_used":0,"verdict":"success","summary":{"kind":"count","noun":"person","count":0}}]'::jsonb, 30)
  ) m(key, role, content, tool_calls, off_s)
JOIN (SELECT l->>'session' AS key, min((l->>'age_s')::int) AS age_s
      FROM seed_data, jsonb_array_elements(d->'lists') l GROUP BY 1) s USING (key)
WHERE NOT EXISTS (SELECT 1 FROM chat_messages c WHERE c.session_id = pg_temp.seed_id(u.id || ':' || m.key));
INSERT INTO lists (id, organization_id, user_id, project_id, chat_session_id, name, entity, created_at)
SELECT pg_temp.seed_id(u.id || ':' || (l->>'id')), default_organization(u.id), u.id,
       (SELECT p.id FROM projects p WHERE p.user_id = u.id AND p.organization_id = default_organization(u.id)
        ORDER BY p.created_at LIMIT 1),
       pg_temp.seed_id(u.id || ':' || (l->>'session')), l->>'name', l->>'entity',
       now() - (l->>'age_s')::int * interval '1 second'
FROM seed_user u, seed_data, jsonb_array_elements(d->'lists') l;

INSERT INTO list_columns (list_id, key, label, kind, position, config)
SELECT pg_temp.seed_id(u.id || ':' || (l->>'id')), c->>'key', c->>'label', c->>'kind', (c->>'position')::int, c->'config'
FROM seed_user u, seed_data, jsonb_array_elements(d->'lists') l, jsonb_array_elements(l->'columns') c;

INSERT INTO list_rows (id, list_id, cells, cell_meta, relevance_score, score_reasons, dedupe_key,
                       excluded, rating, rating_note, created_at)
SELECT pg_temp.seed_id(u.id || ':' || (r->>'id')), pg_temp.seed_id(u.id || ':' || g.key), r->'cells', r->'cell_meta',
       (r->>'relevance_score')::numeric, nullif(r->'score_reasons', 'null'::jsonb), r->>'id',
       (r->>'excluded')::boolean, r->>'rating', r->>'rating_note',
       now() - (r->>'age_s')::int * interval '1 second'
FROM seed_user u, seed_data, jsonb_each(d->'rows') g(key, rs), jsonb_array_elements(g.rs) WITH ORDINALITY x(r, n)
ORDER BY g.key, x.n;

\endif

SELECT (SELECT count(*) FROM lists WHERE user_id = u.id) AS lists,
       (SELECT count(*) FROM list_rows r JOIN lists l ON l.id = r.list_id WHERE l.user_id = u.id) AS rows,
       (SELECT count(*) FROM chat_sessions WHERE user_id = u.id) AS chats
FROM seed_user u;
COMMIT;
